Study this Java implementation of Agile team velocity calculation:

public class AgileTeam {
    private int[] sprintVelocities;

    public AgileTeam() {
        sprintVelocities = new int[]{15, 18, 12, 21};
    }

    public double calculateAverageVelocity() {
        int sum = 0;
        for (int i = 0; i < sprintVelocities.length; i++) {
            sum += sprintVelocities[i];
        }
        return sum / sprintVelocities.length;
    }
}

